  getOOSCstuList(event){
    console.log('event',event)
    this.toBeAdmitted = [];
    this.toBeVerified = [];
    this.toBeSurvey = [];
    this.nonTarget = [];
    this.studList = [];
    this.emisUser.getAccListSurvey(this.teacher_id,event).subscribe(res => {
      console.log('getAccListSurvey',res)
      if (res.dataStatus == true) {
        this.studList = res.result;

        for (let i = 0; i < this.studList.length; i++) {
          if(this.studList[i].reason_type == 'To be admitted') {
            this.toBeAdmitted.push(this.studList[i]);
          }
    
          if(this.studList[i].reason_type == "To be verified") {
            this.toBeVerified.push(this.studList[i]);
          }
    
          if(this.studList[i].reason_type == 'To be survey') {
            this.toBeSurvey.push(this.studList[i]);
          }        
    
          if(this.studList[i].reason_type == 'Non-Target') {
            this.nonTarget.push(this.studList[i]);
          }  
         }
        this.studListCopy = this.studList
        console.log('stuList', this.studList);


      } else {
        this.studList = [];
      }
    })    

    console.log('toBeAdmitted:',this.toBeAdmitted, 'toBeVerified:',this.toBeSurvey, 'toBeSurvey:', )

  }


  getNvrEnrollmentStuList() {  
    this.emisUser.getNvrEnrolmentStudentListForBRTE(this.teacher_id).subscribe(res => {
      this.studList = res.result;
      this.studListCopy = this.studList
      console.log('stuList', this.studList);
    })
  }

